/** A snapshot plan's name is user-editable, but nobody types one for a plan they built by clicking
 *  a preset — so a preset click also names the plan, using the preset's own button text.
 *
 *  That must never overwrite a name the user wrote, which is what `allPresetLabels` is for: a name
 *  generated by a preset is free to be replaced, anything else is the user's own and stays.
 *
 *  The comparison drops a trailing clock (`03:00`, `03:00:00`) from both sides, because a name a
 *  preset wrote earlier can be just the cadence (`每周日`) while today's preset text carries the
 *  time (`每周日 03:00`) — seeing those as different is what made a preset click look like a no-op. */
const TRAILING_TIME = /\s*\d{1,2}:\d{2}(:\d{2})?\s*$/

function cadenceOnly(label: string): string {
  return label.replace(TRAILING_TIME, "").trim()
}

export function labelAfterPreset(
  currentLabel: string,
  presetLabel: string,
  allPresetLabels: readonly string[],
): string {
  const trimmed = currentLabel.trim()
  if (trimmed === "") return presetLabel
  const current = cadenceOnly(trimmed)
  const generated = allPresetLabels.some((label) => cadenceOnly(label) === current)
  return generated ? presetLabel : currentLabel
}
